import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  title = 'mvc-angular-demo';
}

<!-- src/app/app.component.html -->
<header class="header-app">
  <h1>Sistema de Nómina - Arquitectura MVC en Angular</h1>
  <nav class="menu-navegacion">
    <a routerLink="/empleados" routerLinkActive="activo">Lista de Empleados (Vista Listado)</a>
    <a routerLink="/nuevo-empleado" routerLinkActive="activo">+ Nuevo Registro (Vista Formulario)</a>
  </nav>
</header>
<main class="contenedor-principal">
  <!-- Despachador del Front Controller de Angular -->
  <router-outlet></router-outlet>
</main>
